import { useParams, useNavigate } from "react-router-dom";
import StartScreen from "./StartScreen";
import { useMemo, useState } from "react";

function Quiz({ quizzes = [] }) {
  const { id } = useParams();
  const [started, setStarted] = useState(false);
  const [studentName, setStudentName] = useState("");

  const quiz = useMemo( () => {
    return quizzes.find( (q) => String(q.id) === String(id) );
  }, [quizzes, id]);

  const navigate = useNavigate();


  if (!quiz) {
    return (
      <div>
        <p>Nie znaleziono quizu.</p>
        <button onClick={() => navigate("/")}>Wróć do listy quizów</button>
      </div>
    );
  }

  return (
    <div className="maturazinformatyki-quiz">
      <h1>{quiz.title}</h1>
      <p><strong>Opis:</strong> {quiz.content}</p>
      <p><strong>Poziom:</strong> {quiz.level}</p>
      <p><strong>Liczba pytań:</strong> {quiz.questions}</p>

      <StartScreen
        onStart={(name)=>{
          setStudentName(name);
          setStarted(true);
        }}
        defaultName={studentName}
        nameQuiz={quiz.name}
      />
      <button onClick={() => navigate("/")}>
        Wróć do listy quizów
      </button>
    </div>
  );
}

export default Quiz;
